const normalIds=new Set(['dkvb','none','none_known','normal','clean','clear','seated','secure','aligned','available','alternative_safe_tool','within_limit','recorded','consistent','stable','comparable','tracks_target','request_held','moves_smoothly','intact','smooth','ready','completed','recovered','dry','no_clue','no_support','return_to_controls','no','normal_consistent','not_moved','tracks','continue_here','new_record','resolved','not_returned','demo_pass']);
