const human=(id:string)=>labelMap[id]??id.replaceAll('_',' / ');
const parseFields=(spec=''):FieldDef[]=>spec?spec.split(';').map(part=>{const [id,label,unit,defaultValue,type]=part.split('|');return{id,label,unit:unit||undefined,defaultValue,type:type==='number'?'number':'text'}}):[];
const stageText:Record<StageId,[string,string]>={S0:['确认病例身份、症状边界和安全条件。','核对接诊信息后选择结构化答案。'],S1:['从可见且低风险的空气路径寻找限制、松脱或泄漏。','沿空气路径检查；加压不得超过0.5 bar。'],S2:['确认压力信号与采集工况是否可信。','先做静态比较，再记录三个可比较负荷帧。'],S3:['检查V465、N249、连杆和模拟设置线索。','记录连接和响应，不从单项失败跳到换件。'],S4:['在不拆解前提下收集涡轮外部线索。','仅做安全可见检查；多类线索才支持专业检测。'],S5:['在增压恢复或伴随故障码时扩展方向。','记录点火、燃油、排气和进气事实，只形成方向建议。'],S6:['把处理前事实、处理动作和新复检分开保存。','新建复检记录，不覆盖处理前事实。']};
export const questionBlocks:QuestionBlock[]=rawQuestions.map(([id,stageRaw,cardId,prompt,ids,factKey,fieldSpec,assets])=>{const stage=stageRaw as StageId;return{id,stage,cardId,title:`${id} · ${prompt.replace(/[？?]$/,'')}`,prompt,purpose:stageText[stage][0],instructions:stageText[stage][1],factKey,fields:parseFields(fieldSpec),assetIds:assets?.split(' ').filter(Boolean)??[],sources:stage==='S1'||assets?.includes('M')||assets?.includes('E')?['FACT_LOCAL_MANUAL',...(stage==='S2'||stage==='S3'||stage==='S5'?['EDITORIAL_DEMO' as SourceType]:[])]:stage==='S4'?['GENERAL_VAG_REFERENCE','SAFETY_BOUNDARY']:['EDITORIAL_DEMO'],options:ids.split(' ').map(id=>({id,label:human(id),outcome:unavailableIds.has(id)?'unavailable':stage==='S0'?(id==='stop_now'||id==='caution'?'abnormal':'normal'):normalIds.has(id)?(id==='recovered'||id==='demo_pass'?'recovered':'normal'):'abnormal'}))}});

const card=(id:string,stage:StageId,areaId:AreaId|undefined,title:string,icon:string,location:string,why:string,assets=''):TopicCard=>({id,stage,areaId,title,icon,location,why,safety:stage==='S4'?'只做外部非拆解检查，不输出部件定罪或换件建议。':stage==='S1'?'压力检漏不得超过0.5 bar；条件不足时保守交接。':'记录事实，不根据单项现象直接形成换件结论。',questionIds:questionBlocks.filter(q=>q.cardId===id).map(q=>q.id),assetIds:assets.split(' ').filter(Boolean)});
